import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.BV21bweQ.js";const _=JSON.parse('{"title":"自然生态","description":"","frontmatter":{},"headers":[],"relativePath":"表层/地理/自然生态.md","filePath":"表层/地理/自然生态.md","lastUpdated":1787066340000}'),i={name:"表层/地理/自然生态.md"};function o(h,a,n,d,s,c){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="自然生态" tabindex="-1">自然生态 <a class="header-anchor" href="#自然生态" aria-label="Permalink to &quot;自然生态&quot;">​</a></h1><h2 id="六边形沙漠" tabindex="-1">六边形沙漠 <a class="header-anchor" href="#六边形沙漠" aria-label="Permalink to &quot;六边形沙漠&quot;">​</a></h2><p>大陆上一片看起来不像是自然形成的诡异沙漠，呈规则的六边形几何特征，温度奇高，与周边环境差异鲜明，且近百年持续升温，逐渐成为无活物可生存的无人区。沙漠深处岩石层内有极其危险的橙黄色高能晶体矿物，被狮族作为极高能炸药与极高能燃料使用。</p><h2 id="极北之地" tabindex="-1">极北之地 <a class="header-anchor" href="#极北之地" aria-label="Permalink to &quot;极北之地&quot;">​</a></h2><p>熊族的家园，环境恶劣，低温与土壤条件均不佳，农业发展严重受限，粮食供应长期紧张，但工业资源丰厚，支撑着熊国强大的工业体系。</p><h2 id="古环形山" tabindex="-1">古环形山 <a class="header-anchor" href="#古环形山" aria-label="Permalink to &quot;古环形山&quot;">​</a></h2><p>大陆上随处可见或大或小的环形山，被普遍视为自然地形地貌，但看起来的确不像是自然形成的。</p><h2 id="南方深山密林" tabindex="-1">南方深山密林 <a class="header-anchor" href="#南方深山密林" aria-label="Permalink to &quot;南方深山密林&quot;">​</a></h2><p>兔族的栖息地，位于大陆南方。此地道路难行、瘴气弥漫、极易迷路，大规模武装进入的成本与收益完全不成比例，是兔族在黑暗时代得以保持相对独立的地形壁垒。</p><h2 id="旧都水域" tabindex="-1">旧都水域 <a class="header-anchor" href="#旧都水域" aria-label="Permalink to &quot;旧都水域&quot;">​</a></h2><p>共同体旧都沉没后形成的水域，曾经的繁华都城如今沉睡于水面之下，是大陆上著名的水下遗迹。</p><h2 id="锤头山" tabindex="-1">锤头山 <a class="header-anchor" href="#锤头山" aria-label="Permalink to &quot;锤头山&quot;">​</a></h2><p>传说中龙族的隐居之地。龙族曾见于文献甚至史书之中，却不知何时忽然消失，如今不再现世，寻找者往往无功而返。&quot;锤头山&quot;之名仅存于传说之中，其位置始终无人能够确证。</p><hr><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./古代遗迹">古代遗迹</a></li><li><a href="./../种族/兔族">兔族</a></li><li><a href="./../种族/龙族">龙族</a></li><li><a href="./../../中层/世界/太空巨构" class="layer-link" data-layer="中层">太空巨构</a></li></ul><hr>',17)])])}const p=e(i,[["render",o]]);export{_ as __pageData,p as default};
